        for (let k = 0; k < step.lines && k < f.lines; k++) lines[k] = `export const ${ident(f.path)}_${k} = ${k} * 2; // reworked`;
        writeRepoFile(repo, f.path, lines.join("\n"));
        const subject = `human: rework ${f.path}`;
